  (201, true, '201|||סיוע וליווי, חינוך ומניעה, קבוצות תמיכה (פרונטלי וזום)', '201|||סיוע וליווי לנפגעות ולנפגעי תקיפה מינית ולבני משפחותיהם, וגם טיפול רגשי. המפגשים פנים אל פנים או בזום.', '{"whatsapp":"","whatsappLabel":"","cost":"","founded":"1998","meeting":"both","specialty":"תקיפה מינית","approaches":"קבוצות תמיכה, טיפול רגשי בצילום","notes":"ההשתתפות בקבוצות בתשלום סמלי. קווי 1202 ו-1203 הם של איגוד מרכזי הסיוע, בכרטיס נפרד.","target":"נפגעות ונפגעי תקיפה מינית ובני משפחותיהם","region":"השפלה המורחבת","org":"תאיר – מרכז הסיוע לנפגעות ולנפגעי תקיפה מינית","svc":"סיוע וליווי לנפגעות ולנפגעי תקיפה מינית ולבני משפחותיהם, וגם טיפול רגשי. המפגשים פנים אל פנים או בזום.","phone":"08-949-6020","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"","emailLabel":"","emailShowAddress":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false}'::jsonb, '{"whatsapp":"","whatsappLabel":"","cost":"","founded":"1998","meeting":"both","specialty":"Sexual assault","approaches":"Support groups, emotional treatment through photography","notes":"Joining a group has a token fee. The 1202 and 1203 lines belong to the Association of Rape Crisis Centers, on a separate card.","target":"People who experienced sexual assault and their families","region":"The greater Shephelah","org":"Tair – Assistance Center for Victims of Sexual Assault","svc":"Assistance and accompaniment for people who experienced sexual assault and for their families, and also emotional treatment. Meetings are in person or on Zoom.","phone":"08-949-6020","phoneLabel":"Phone","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phon