  (203, true, '203|||רשת ארצית לטיפול פסיכולוגי, אבחון והכשרה — כולל טיפול בטראומה ובמצוקה נפשית.', '203|||פסיכותרפיה, וגם טיפול פסיכיאטרי. רשת בפריסה ארצית.', '{"whatsapp":"","whatsappLabel":"","cost":"","founded":"","meeting":"","specialty":"דיכאון, חרדה, קשב, טראומה, הפרעות אכילה","approaches":"CBT, טיפול דינמי, טיפול באומנות, טיפול זוגי ומשפחתי","notes":"","target":"ילדים, נוער ומבוגרים","region":"כל הארץ","org":"ת.ל.מ","svc":"פסיכותרפיה, וגם טיפול פסיכיאטרי. רשת בפריסה ארצית.","phone":"074-7292600","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"","emailLabel":"","emailShowAddress":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false}'::jsonb, '{"whatsapp":"","whatsappLabel":"","cost":"","founded":"","meeting":"","specialty":"Depression, anxiety, ADHD, trauma, eating disorders","approaches":"CBT, dynamic therapy, art therapy, couples and family therapy","notes":"","target":"Children, youth, and adults","region":"Nationwide","org":"Telem","svc":"Psychotherapy, and also psychiatric treatment. A nationwide network.","phone":"074-7292600","phoneLabel":"Phone","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email":"","emailLabel":"","email2":"","emailLabel2":"","email3":"","emailLabel3":""}'::jsonb, '23.11.2026: נבדק מול https://www.telem.org.il/. הניסוח אושר עם אצוות הטראומה.'),
  (206, true, '206|||מודל נשימה — טיפול מסובסד, רשת מטפלים לטראומה מורכבת וגישת גוף–נפש קהילתית.', '206|||האתר בבנייה. אפשר לפנות בטלפון או באימייל.', '{"whatsapp":"","whatsappLabel":"","cost":"","founded":"","meeting":"","specialty":"","approaches":"","notes":"","target":"","region":"","org":"מרכז נשימה","svc":"האתר בבנייה. אפשר לפנות בטלפון או באימייל.","phone":"054-8344151","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"Neshima.ptsd@gmail.com","emailLabel":"אימייל","emailShowAddress":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false}'::jsonb, '{"whatsapp":"","whatsappLabel":"","cost":"","founded":"","meeting":"","specialty":"","approaches":"","notes":"","target":"","region":"","org":"Neshima Center","svc":"The site is under construction. You can call or write.","phone":"054-8344151","phoneLabel":"Phone","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email":"Neshima.ptsd@gmail.com","emailLabel":"Email","email2":"","emailLabel2":"","email3":"","emailLabel3":""}'::jsonb, '23.11.2026: נבדק מול https://neshima-ptsd.co.il/. הניסוח אושר עם אצוות הטראומה.'),
  (210, true, '210|||טיפול ארצי ללא עלות לטווח ארוך בטראומה', '210|||פסיכותרפיה לנפגעי טראומה ואובדן. במרפאה.', '{"whatsapp":"","whatsappLabel":"","cost":"","founded":"1989","meeting":"in_person","specialty":"טראומה, אובדן, PTSD","approaches":"","notes":"יש טיפולים ללא עלות למתמודדים עם PTSD, ברחבי הארץ. המרפאה במרכז הרפואי הרצוג, גבעת שאול. הסיכה על המפה עדיין על הדסה עין כרם.","target":"נפגעי טראומה ואובדן","region":"ירושלים, כל הארץ","org":"מטיב – המרכז הישראלי לפסיכוטראומה","svc":"פסיכותרפיה לנפגעי טראומה ואובדן. במרפאה.","phone":"02-644-9666","phoneLabel":"משרד","phoneShowNumber":false,"phone2":"02-595-2234","phoneLabel2":"מרפאה","phoneShowNumber2":false,"phone3":"02-6294858","phoneLabel3":"ילדים","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"info@metiv.org","emailLabel":"אימייל","emailShowAddress":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false}'::jsonb, '{"whatsapp":"","whatsappLabel":"","cost":"","founded":"1989","meeting":"in_person","specialty":"Trauma, loss, PTSD","approaches":"","notes":"There is treatment at no cost for people with PTSD, across the country. The clinic is at Herzog Medical Center, Givat Shaul. The map pin is still on Hadassah Ein Kerem.","target":"People affected by trauma and loss","region":"Jerusalem, nationwide","org":"Metiv – Israel Psychotrauma Center","svc":"Psychotherapy for people affected by trauma and loss. At the clinic.","phone":"02-644-9666","phoneLabel":"Office","phone2":"02-595-2234","phoneLabel2":"Clinic","phone3":"02-6294858","phoneLabel3":"Children","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email":"info@metiv.org","emailLabel":"Email","email2":"","emailLabel2":"","email3":"","emailLabel3":""}'::jsonb, '23.11.2026: נבדק מול https://metiv.org.il/ ו-https://metiv.